import { useCallback, useEffect, useMemo, useState } from "react";
import Swal from "sweetalert2";
import data from "../noun.json";
import InfoPopUpForDetailView from "./InfoPopUpForDetailView.js";
import ViewDetailsPopup from "./ViewDetailsPopup.js";
import { useNavigate } from "react-router-dom";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";
import hintImg from "../Images/hint2.png";
import Tooltip, { tooltipClasses } from "@mui/material/Tooltip";
import { styled } from "@mui/material/styles";
import { useTranslation } from "react-i18next";
import "../css/common.css";
import ReactGA from "react-ga4";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import useWebSocket, { ReadyState } from "react-use-websocket";

export const Level1MidContent = () => {
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const { t } = useTranslation();
  const [pageName, setpageName] = useState("Level-1");
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  let navigate = useNavigate();
  let [showDialogue, setShowDialogue] = useState(false);
  let [isDisableNext, setIsDisableNext] = useState(true);
  let [skipCount, setSkipCount] = useState(0);
  let [isDisableButtons, setIsDisableButtons] = useState(true);
  let [word, setWord] = useState("");
  let [selectedNounArray, setSelectednounArray] = useState([]);
  let [nounTypeArray, setNounTypeArray] = useState([]);
  const [wordColors, setWordColors] = useState({});
  const [showMessage, setShowMessage] = useState(false);
  const [selectedNounWord, setSelectedNounWord] = useState("");
  const [selectedNounType, setSelectedNounType] = useState("");

  //Flag to make buttons green or red
  const [commonNounButtonColor, setCommonNounButtonColor] = useState("#F5B946");
  const [properNounButtonColor, setProperNounButtonColor] = useState("#F5B946");
  const [abstractNounButtonColor, setAbstractNounButtonColor] =
    useState("#F5B946");
  const [collectiveNounButtonColor, setCollectiveNounButtonColor] =
    useState("#F5B946");

  let [showErrorMessage, setShowErrorMessage] = useState(false);
  let [nounType, setNounType] = useState("");
  let [level, setLevel] = useState("Level 1");

  const LightTooltip = styled(({ className, ...props }) => (
    <Tooltip {...props} classes={{ popper: className }} />
  ))(({ theme }) => ({
    [`& .${tooltipClasses.tooltip}`]: {
      backgroundColor: theme.palette.common.white,
      color: "rgba(0, 0, 0, 0.87)",
      boxShadow: theme.shadows[1],
      fontSize: 14,
    },
  }));

  // Memoize noun buttons to avoid re-creation on each render
  const nounButtons = useMemo(
    () => [
      {
        label: "Common noun",
        bgcolor: commonNounButtonColor,
        key: "common noun",
      },
      {
        label: "Proper noun",
        bgcolor: properNounButtonColor,
        key: "proper noun",
      },
      {
        label: "Abstract noun",
        bgcolor: abstractNounButtonColor,
        key: "abstract noun",
      },
      {
        label: "Collective noun",
        bgcolor: collectiveNounButtonColor,
        key: "collective noun",
      },
    ],
    [
      commonNounButtonColor,
      properNounButtonColor,
      abstractNounButtonColor,
      collectiveNounButtonColor,
    ]
  );

  // Reset button colors whenever `word` changes
  useEffect(() => {
    setCommonNounButtonColor("#F5B946");
    setProperNounButtonColor("#F5B946");
    setAbstractNounButtonColor("#F5B946");
    setCollectiveNounButtonColor("#F5B946");
  }, [word]);

  // Enable Next button only if all nouns have been selected
  useEffect(() => {
    if (
      selectedNounArray.length === nounTypeArray.length &&
      selectedNounArray.length === data.Level1[randomNumber].noun.nouns.length
    ) {
      setIsDisableNext(false);
    } else {
      setIsDisableNext(true);
    }
  }, [selectedNounArray, nounTypeArray, randomNumber]);

  // Avoid recursive call, use a loop to find a unique random number
  const getUniqueRandomNumber = (excludeList, max) => {
    if (excludeList.length >= max) return null;
    let rand;
    do {
      rand = Math.floor(Math.random() * max);
    } while (excludeList.includes(rand));
    return rand;
  };

  const handleNext = useCallback(() => {
    setWord("");
    setWordColors({});
    setIsDisableNext(true);
    setNounTypeArray([]);
    setSelectednounArray([]);
    setIsDisableButtons(true);
    setShowErrorMessage(false);

    setSelectedNounWord("");
    setSelectedNounType("");
    setShowMessage(false);

    if (randomNumberArray.length < 10) {
      const nextRandom = getUniqueRandomNumber(
        randomNumberArray,
        data.Level1.length
      );
      if (nextRandom !== null) {
        setRandomNumber(nextRandom);
        setRandomNumberArray((prev) => [...prev, nextRandom]);
      }
    } else {
      navigate("/launchpage/englishactivity/selectlevel/restart", {
        state: {
          attempted: 10 - skipCount,
          levelName: "Single noun and its type",
          levelToRestart: "Level 1",
        },
      });
    }
  }, [randomNumberArray, skipCount, navigate, pageName]);

  const handleButtonClick = useCallback(
    (buttonname) => {
      const correctNouns = {
        "common noun": data.Level1[randomNumber].noun.common,
        "proper noun": data.Level1[randomNumber].noun.proper,
        "abstract noun": data.Level1[randomNumber].noun.abstract,
        "collective noun": data.Level1[randomNumber].noun.collective,
      };

      // Reset all colors first
      setCommonNounButtonColor("#F5B946");
      setProperNounButtonColor("#F5B946");
      setAbstractNounButtonColor("#F5B946");
      setCollectiveNounButtonColor("#F5B946");

      if (correctNouns[buttonname]?.includes(word)) {
        // Set green color for clicked button
        switch (buttonname) {
          case "common noun":
            setCommonNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            break;
          case "proper noun":
            setProperNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            break;
          case "abstract noun":
            setAbstractNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            break;
          case "collective noun":
            setCollectiveNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            break;
        }
        setNounTypeArray((prev) => [...prev, buttonname]);
        setShowErrorMessage(false);

        setSelectedNounType(buttonname); // 👈 Set selected correct noun type here
      } else {
        // Set red color for wrong choice
        switch (buttonname) {
          case "common noun":
            setCommonNounButtonColor("#BF4C4C");
            break;
          case "proper noun":
            setProperNounButtonColor("#BF4C4C");
            break;
          case "abstract noun":
            setAbstractNounButtonColor("#BF4C4C");
            break;
          case "collective noun":
            setCollectiveNounButtonColor("#BF4C4C");
            break;
        }
        setNounType(buttonname);
        setShowErrorMessage(true);
      }
    },
    [randomNumber, word, pageName]
  );

  const handleWordClick = (clickedWord) => {
    setShowErrorMessage(false);

    // Clean up clicked word
    let newWord = clickedWord
      .replace(/[^\w\s]|_/g, "")
      .replace(/\s+/g, "")
      .replace(/\./g, "");

    setWord(newWord);

    const isNoun = data.Level1[randomNumber].noun.nouns.includes(newWord);

    setWordColors((prevColors) => ({
      ...prevColors,
      [clickedWord]: isNoun ? "#098B0D" : "#BF4C4C", // green or red
    }));

    if (isNoun) {
      setIsDisableButtons(false);
      setSelectedNounWord(newWord);
      if (!selectedNounArray.includes(newWord))
        setSelectednounArray((prev) => [...prev, newWord]);
    } else {
      setIsDisableButtons(true);
      setSelectedNounWord("");
    }

    ReactGA.event({
      action: `Eng4|Noun|Clicked on "${clickedWord}" word of a sentence in level 1`,
      category: `Eng4|"${clickedWord}" word clicked`,
      label: `Eng4|Clicked on "${clickedWord}" word`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      `${clickedWord} word clicked`,
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    setWord("");
    setWordColors({});
    handleNext();
    ReactGA.event({
      action: `Eng4|Noun|Clicked on "skip" button of level-1`,
      category: `Eng4|skip button clicked`,
      label: `Eng4|Clicked on skip button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "skip",
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleHint = () => {
    setShowDialogue(true);
    ReactGA.event({
      action: `Eng4|Noun|Clicked on "hint" button of level-1`,
      category: `Eng4|hint button clicked`,
      label: `Eng4|Clicked on hint button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "hint",
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const onAgree = () => {
    setShowDialogue(false);
  };

  const handleLevelChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/selectlevel/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/selectlevel/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
    ReactGA.event({
      action: `Eng4|Noun|Clicked on "select level dropdown" of level-1`,
      category: `Eng4|select level dropdown clicked`,
      label: `Eng4|Clicked on select level dropdown`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "select level dropdown",
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
            fontSize: "calc(.6rem + .4vw)",
          }}
        >
          <div className="row align-items-center mb-5 mt-2">
            <div className="col-12 col-md-6 d-flex justify-content-end mb-2 mb-md-0">
              <div
                className="fw-bolder"
                style={{ fontSize: "calc(1rem + .4vw)" }}
              >
                Single noun and its type
              </div>
            </div>

            <div className="col-12 col-md-6 d-flex justify-content-md-end justify-content-center">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                    fontSize: "calc(.6rem + .4vw)",
                  }}
                >
                  <MenuItem value="Level 1">{t("level1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level2")}</MenuItem>
                </Select>
              </FormControl>

              <img
                onClick={handleHint}
                style={{
                  marginLeft: "20px",
                  cursor: "pointer",
                  height: "40px",
                  width: "40px",
                }}
                title={t("hint_tooltip")}
                src={hintImg}
                alt="logo"
              />
            </div>
          </div>

          <div className="row">
            <div className="d-flex align-items-center mb-3">
              <span className="me-3">Sentence</span>
              <Slider
                defaultValue={0}
                step={1}
                min={1}
                max={10}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="col-md-6 text-center"
                style={{
                  height: "50px",
                  width: "50px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  marginLeft: "2%",
                }}
              >
                {randomNumberArray.length}/10
              </span>
            </div>
          </div>

          <div
            className="row mb-3"
            style={{
              background: "#EDF6FA",
              padding: "20px 0",
              borderRadius: "10px",
            }}
          >
            <div className="row text-center">
              <div className="fw-bolder mb-3 text-center">
                {data.Level1[randomNumber].sentence}
              </div>
            </div>

            <div className="row text-center">
              <div className="mb-2">
                {data.Level1[randomNumber].sentence
                  .split(" ")
                  .map((word, index) => {
                    const isDisabled =
                      selectedNounWord !== "" && word !== selectedNounWord;
                    return (
                      <button
                        className="button mb-1"
                        key={index}
                        onClick={() => handleWordClick(word)}
                        disabled={isDisabled}
                        style={{
                          backgroundColor: wordColors[word] || "#F5B946",
                          color: wordColors[word] ? "#FFFFFF" : "#000",
                          fontWeight: "bold",
                          cursor: isDisabled ? "not-allowed" : "pointer",
                        }}
                      >
                        {word}
                      </button>
                    );
                  })}
              </div>
            </div>

            <div className="row text-center">
              {word && (
                <div className="mb-3">
                  {data.Level1[randomNumber].noun.nouns.includes(word) ? (
                    <div style={{ color: "#098B0D" }}>
                      <q>{word}</q> is a noun word.
                    </div>
                  ) : (
                    <div style={{ color: "#BF4C4C" }}>
                      <q>{word}</q> is not a noun word.
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="row text-center">
              <div className="mb-3">
                {!isDisableButtons && (
                  <div style={{ color: "#BF4C4C" }}>
                    Please select the type of noun for <q>{word}</q>.
                  </div>
                )}
              </div>
            </div>

            <div className="row">
              <div className="mb-3 d-flex flex-wrap justify-content-between gap-2">
                {nounButtons.map(({ label, bgcolor, color, key }) => {
                  const isDisabled =
                    isDisableButtons ||
                    (selectedNounType !== "" && key !== selectedNounType);

                  return (
                    <button
                      className="button"
                      key={key}
                      disabled={isDisabled}
                      onClick={() => handleButtonClick(key)}
                      style={{
                        backgroundColor: bgcolor || color,
                        color: bgcolor === "#F5B946" ? "#000" : "#FFFFFF",
                        fontWeight: "bold",
                        flexShrink: 0,
                        padding: "0.5rem 1rem",
                        cursor: isDisabled ? "not-allowed" : "pointer",
                      }}
                    >
                      {label}
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="row text-center">
              <div className="row justify-content-center">
                {showErrorMessage && (
                  <div style={{ color: "#BF4C4C" }}>
                    <q>{word}</q> is not{" "}
                    {nounType === "abstract noun" ? "an" : "a"} {nounType}.
                    Refer hint.
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="row ">
            <div className="mb-3 d-flex justify-content-around">
              <Button
                variant="contained"
                onClick={handleSkip}
                sx={{
                  background: "#0F477E",
                  color: "#ffffff",
                  fontSize: "calc(.6rem + .4vw)",
                }}
              >
                {t("skip")}
              </Button>
              <Button
                variant="contained"
                disabled={isDisableNext}
                onClick={handleNext}
                sx={{
                  background: "#0F477E",
                  color: "#ffffff",
                  fontSize: "calc(.6rem + .4vw)",
                }}
              >
                {randomNumberArray.length == 10 ? t("finish") : t("next")}
              </Button>
            </div>
          </div>

          <div className="row justify-content-center">
            {showMessage && (
              <div
                className="d-flex justify-content-center align-items-center"
                style={{
                  width: "auto",
                  height: "auto",
                  background: "#ffffff",
                  boxShadow: "0px 0px 5px rgba(0, 0, 0, 0.5)",
                  borderRadius: "50px",
                  padding: "1rem",
                }}
              >
                <div>
                  Correct!{" "}
                  <span style={{ color: "#098B0D", fontWeight: "bold" }}>
                    {selectedNounWord}
                  </span>{" "}
                  is a noun and it is a{" "}
                  <span style={{ color: "#098B0D", fontWeight: "bold" }}>
                    {selectedNounType}
                  </span>
                  .
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <div>
              {!isDisableNext ? (
                <ul>
                  {randomNumberArray.length === 10 ? (
                    <li>{t("instr9")}</li>
                  ) : (
                    <li>{t("instr2_7")}</li>
                  )}
                </ul>
              ) : randomNumberArray.length > 10 == true ? (
                <ul className="">
                  <li>{t("instr8")}</li>
                </ul>
              ) : (
                <ul className="">
                  <li>{t("instr1")}</li>
                  <li>{t("instr2")}</li>
                  <li>{t("instr3")}</li>
                  <li>{t("instr4")}</li>
                  <li>{t("instr5")}</li>
                  <li>
                    <u>{t("note")}</u>: {t("instr7")}
                  </li>
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>
      <InfoPopUpForDetailView
        openDialog={showDialogue}
        onAgree={onAgree}
        content={<ViewDetailsPopup hint={data.Level1[randomNumber].hint} />}
        popuptitle="Hint"
      />
    </div>
  );
};
