import Slide from "@mui/material/Slide";
import CloseIcon from "@material-ui/icons/Close";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
} from "@mui/material";
import { useTranslation } from "react-i18next";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="top" ref={ref} {...props} />;
});
const InfoPopUpForDetailView = ({
  openDialog,
  onAgree,
  content,
  popuptitle,
}) => {
  const { t } = useTranslation();
  return (
    <>
      <Dialog
        open={openDialog}
        TransitionComponent={Transition}
        maxWidth="lg"
        className="text-center"
      >
        <DialogTitle
          style={{ backgroundColor: "#90D5FF", fontSize: "calc(.6rem + .4vw)" }}
        >
          <Box display="flex" alignItems="center">
            <Box flexGrow={1}>
              <h1 className="fw-bolder">{popuptitle}</h1>
            </Box>
            <Box>
              <IconButton onClick={onAgree}>
                <CloseIcon />
              </IconButton>
            </Box>
          </Box>
        </DialogTitle>
        <DialogContent dividers>{content}</DialogContent>
        <DialogActions className="d-flex justify-content-center me-5">
          <Button
            variant="contained"
            style={{
              fontSize: "calc(.6rem + .2vw)",
              backgroundColor: "#0F477E",
            }}
            onClick={onAgree}
          >
            {t("close")}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default InfoPopUpForDetailView;
