import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import nounVideo from "../videos/English Noun 3.mp4";
import { Button } from "@mui/material";
import ReactGA from "react-ga4";
import { useTranslation } from "react-i18next";

const FirstVideoPageMidContent = () => {
  const { t } = useTranslation();
  const [pageName, setpageName] = useState("Starting video page");
  const [orientation, setOrientation] = useState("landscape");
  let navigate = useNavigate();

  // Function to check the device orientation
  const checkOrientation = () => {
    if (window.innerHeight > window.innerWidth) {
      setOrientation("portrait");
    } else {
      setOrientation("landscape");
    }
  };

  // Hook to update the orientation on window resize
  useEffect(() => {
    checkOrientation();
    window.addEventListener("resize", checkOrientation);
    return () => {
      window.removeEventListener("resize", checkOrientation);
    };
  }, []);

  let handleClick = () => {
    navigate("/launchpage/englishactivity/selectlevel");
  };

  return (
    <div className="container-fluid">
      <div className="p-3" style={{ height: "100%", width: "100%" }}>
        <div
          className="row"
          style={{
            height: "95%",
            backgroundColor: "lightgray",
            position: "relative",
          }}
        >
          <video
            autoPlay
            controls
            style={{
              position: "absolute",
              top: "0",
              left: "0",
              width: "100%",
              height: "100%",
              objectFit: orientation === "landscape" ? "cover" : "contain",
            }}
          >
            <source src={nounVideo} type="video/mp4" />
            Your browser does not support the video tag.
          </video>
        </div>

        <div
          className="row d-flex align-items-center justify-content-center"
          style={{ height: "5%" }}
        >
          <div className="text-center">
            <Button
              variant="contained"
              onClick={handleClick}
              sx={{
                background: "#0F477E",
                fontSize: "calc(.6rem + .4vw)",
                marginTop: "5px",
              }}
            >
              {t("lets_go")}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FirstVideoPageMidContent;
