import { useCallback, useEffect, useMemo, useState } from "react";
import data from "../noun.json";
import InfoPopUpForDetailView from "./InfoPopUpForDetailView.js";
import ViewDetailsPopup from "./ViewDetailsPopup.js";
import { useNavigate } from "react-router-dom";
import { Table } from "react-bootstrap";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";
import hintImg from "../Images/hint2.png";
import { useTranslation } from "react-i18next";
import ReactGA from "react-ga4";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import useWebSocket, { ReadyState } from "react-use-websocket";

export const Level2MidContent = () => {
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const { t } = useTranslation();
  const [nounType, setNounType] = useState("");
  const [pageName] = useState("Level-2");
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomNumberArray, setRandomNumberArray] = useState([0]);
  let navigate = useNavigate();
  let [showDialogue, setShowDialogue] = useState(false);
  let [isDisableNext, setIsDisableNext] = useState(true);
  let [skipCount, setSkipCount] = useState(0);
  let [isDisableButtons, setIsDisableButtons] = useState(true);
  let [word, setWord] = useState("");
  let [selectedNounArray, setSelectednounArray] = useState([]);
  let [nounTypeArray, setNounTypeArray] = useState([]);
  let [commonNounButtonColor, setCommonNounButtonColor] = useState("#F5B946");
  let [properNounButtonColor, setProperNounButtonColor] = useState("#F5B946");
  let [abstractNounButtonColor, setAbstractNounButtonColor] =
    useState("#F5B946");
  let [collectiveNounButtonColor, setCollectiveNounButtonColor] =
    useState("#F5B946");
  let [level] = useState("Level 2");
  const [wordColors, setWordColors] = useState({});
  let [showErrorMessage, setShowErrorMessage] = useState(false);
  let [showMessage, setShowMessage] = useState(false);
  const [isNounLocked, setIsNounLocked] = useState(false);

  // Memoize noun buttons to avoid re-creation on each render
  const nounButtons = useMemo(
    () => [
      {
        label: "Common noun",
        bgcolor: commonNounButtonColor,
        key: "common noun",
      },
      {
        label: "Proper noun",
        bgcolor: properNounButtonColor,
        key: "proper noun",
      },
      {
        label: "Abstract noun",
        bgcolor: abstractNounButtonColor,
        key: "abstract noun",
      },
      {
        label: "Collective noun",
        bgcolor: collectiveNounButtonColor,
        key: "collective noun",
      },
    ],
    [
      commonNounButtonColor,
      properNounButtonColor,
      abstractNounButtonColor,
      collectiveNounButtonColor,
    ]
  );

  // Reset button colors whenever `word` changes
  useEffect(() => {
    setCommonNounButtonColor("#F5B946");
    setProperNounButtonColor("#F5B946");
    setAbstractNounButtonColor("#F5B946");
    setCollectiveNounButtonColor("#F5B946");
  }, [word]);

  // Enable Next button only if all nouns have been selected
  useEffect(() => {
    if (
      selectedNounArray.length === nounTypeArray.length &&
      selectedNounArray.length === data.Level2[randomNumber].noun.nouns.length
    ) {
      setIsDisableNext(false);
    } else {
      setIsDisableNext(true);
    }
  }, [selectedNounArray, nounTypeArray, randomNumber]);

  // Avoid recursive call, use a loop to find a unique random number
  const getUniqueRandomNumber = (excludeList, max) => {
    if (excludeList.length >= max) return null;
    let rand;
    do {
      rand = Math.floor(Math.random() * max);
    } while (excludeList.includes(rand));
    return rand;
  };

  const handleNext = useCallback(() => {
    //States to reset everything.
    setIsDisableNext(true);
    setWord("");
    setNounTypeArray([]);
    setSelectednounArray([]);
    setIsDisableButtons(true);
    setShowErrorMessage(false);
    setWordColors({});
    setShowMessage(false);

    if (randomNumberArray.length < 10) {
      const nextRandom = getUniqueRandomNumber(
        randomNumberArray,
        data.Level1.length
      );
      if (nextRandom !== null) {
        setRandomNumber(nextRandom);
        setRandomNumberArray((prev) => [...prev, nextRandom]);
      }
    } else {
      navigate("/launchpage/englishactivity/selectlevel/restart", {
        state: {
          attempted: 10 - skipCount,
          levelName: "Multiple nouns and its type",
          levelToRestart: "Level 2",
        },
      });

      // Swal.fire({
      //   title: `You have successfully attempted ${
      //     10 - skipCount
      //   } out of 10 sentences!`,
      //   showClass: {
      //     popup: "animate__animated animate__fadeInDown",
      //   },
      //   hideClass: {
      //     popup: "animate__animated animate__fadeOutUp",
      //   },
      //   customClass: {
      //     title: "completeion-text",
      //     htmlContainer: "completeion-text",
      //   },
      //   confirmButtonText: "RESTART",
      // }).then((result) => {
      //   if (result.isConfirmed) {
      //     navigate("/launchpage/englishactivity/selectlevel");
      //   }
      // });
    }
  }, [[randomNumberArray, skipCount, navigate, pageName]]);

  const handleButtonClick = useCallback(
    (buttonname) => {
      setNounType(buttonname);

      const correctNouns = {
        "common noun": data.Level2[randomNumber].noun.common,
        "proper noun": data.Level2[randomNumber].noun.proper,
        "abstract noun": data.Level2[randomNumber].noun.abstract,
        "collective noun": data.Level2[randomNumber].noun.collective,
      };

      // Reset all colors first
      setCommonNounButtonColor("#F5B946");
      setProperNounButtonColor("#F5B946");
      setAbstractNounButtonColor("#F5B946");
      setCollectiveNounButtonColor("#F5B946");

      if (correctNouns[buttonname]?.includes(word)) {
        // ✅ Correct selection – turn button GREEN
        switch (buttonname) {
          case "common noun":
            setCommonNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            setIsNounLocked(false);
            break;
          case "proper noun":
            setProperNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            setIsNounLocked(false);
            break;
          case "abstract noun":
            setAbstractNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            setIsNounLocked(false);
            break;
          case "collective noun":
            setCollectiveNounButtonColor("#098B0D");
            setIsDisableButtons(true);
            setShowMessage(true);
            setIsNounLocked(false);
            break;
        }
        setNounTypeArray((prev) => [...prev, buttonname]);
        setShowErrorMessage(false);
      } else {
        // ❌ Incorrect selection – turn button RED
        switch (buttonname) {
          case "common noun":
            setCommonNounButtonColor("#BF4C4C");
            break;
          case "proper noun":
            setProperNounButtonColor("#BF4C4C");
            break;
          case "abstract noun":
            setAbstractNounButtonColor("#BF4C4C");
            break;
          case "collective noun":
            setCollectiveNounButtonColor("#BF4C4C");
            break;
        }
        setShowErrorMessage(true);
      }
    },
    [randomNumber, word, pageName]
  );

  const handleWordClick = (clickedWord) => {
    if (isNounLocked) return;
    setShowErrorMessage(false);
    // if (!isDisableButtons) return;

    //removing space,special charcter, and full stop and converting it into lowercase.
    const cleanedWord = clickedWord
      .replace(/[^\w\s]|_/g, "")
      .replace(/\s+/g, "")
      .replace(/\./g, "");

    setWord(cleanedWord);

    const isNoun = data.Level2[randomNumber].noun.nouns.includes(cleanedWord);
    setWordColors((prevColors) => ({
      ...prevColors,
      [clickedWord]: isNoun ? "#098B0D" : "#BF4C4C", // green or red
    }));

    if (isNoun) {
      setIsNounLocked(true);
      setIsDisableButtons(false);
      if (!selectedNounArray.includes(cleanedWord)) {
        setSelectednounArray((prev) => [...prev, cleanedWord]);
        setIsDisableButtons(false);
      }
    } else {
      setIsDisableButtons(true);
      setShowMessage(false);
    }

    ReactGA.event({
      action: `Eng4|Noun|Clicked on ${cleanedWord} of level-2`,
      category: `Eng4|${cleanedWord} word clicked`,
      label: `Eng4|Clicked on ${cleanedWord} word`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      `${clickedWord} word clicked`,
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    setWordColors({});
    handleNext();
    ReactGA.event({
      action: `Eng4|Noun|Clicked on "skip" button of level-2`,
      category: `Eng4|skip button clicked`,
      label: `Eng4|Clicked on skip button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "skip",
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const handleHint = () => {
    setShowDialogue(true);
    ReactGA.event({
      action: `Eng4|Noun|Clicked on "hint" button of level-2`,
      category: `Eng4|hint button clicked`,
      label: `Eng4|Clicked on hint button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "hint",
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const onAgree = () => {
    setShowDialogue(false);
  };

  const handleLevelChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/selectlevel/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/selectlevel/level2");
        break;
    }
    ReactGA.event({
      action: `Eng4|Noun|Clicked on "select level dropdown" of level-2`,
      category: `Eng4|select level dropdown clicked`,
      label: `Eng4|Clicked on select level dropdown`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "select level dropdown",
      "Clicked",
      "checking selected option is right or wrong",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            margin: "5px",
            fontSize: "calc(.6rem + .4vw)",
          }}
        >
          <div className="row sticky-top align-items-center mb-5 mt-2">
            {/* Left side: Noun count */}
            <div className="col-12 col-md d-flex align-items-center mb-2 mb-md-0">
              <span className="me-1">Noun count -</span>

              <div
                className="d-flex justify-content-center align-items-center bg-info rounded-circle"
                style={{ width: 40, height: 40, marginLeft: "0.5rem" }}
              >
                {selectedNounArray.length}/
                {data.Level2[randomNumber].noun.nouns.length}
              </div>
            </div>

            <div className="col-12 col-md-6 d-flex justify-content-center mb-2 mb-md-0">
              <div
                className="fw-bolder"
                style={{ fontSize: "calc(1rem + .4vw)" }}
              >
                Multiple nouns and its type
              </div>
            </div>

            {/* Right side: Select and Hint */}
            <div className="col-12 col-md d-flex align-items-center justify-content-md-end">
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                    fontSize: "calc(.6rem + .4vw)",
                  }}
                >
                  <MenuItem value="Level 1">{t("level1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level2")}</MenuItem>
                </Select>
              </FormControl>

              <img
                onClick={handleHint}
                src={hintImg}
                alt="hint icon"
                title={t("hint_tooltip")}
                style={{
                  marginLeft: 16,
                  cursor: "pointer",
                }}
              />
            </div>
          </div>

          <div className="row">
            <div className="d-flex align-items-center mb-3">
              <span className="me-3">Sentence</span>
              <Slider
                defaultValue={0}
                step={1}
                min={1}
                max={10}
                value={randomNumberArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="col-md-6 text-center"
                style={{
                  height: "50px",
                  width: "50px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  marginLeft: "2%",
                }}
              >
                {randomNumberArray.length}/10
              </span>
            </div>
          </div>

          <div
            className="row mb-3"
            style={{
              background: "#EDF6FA",
              padding: "20px 0",
              borderRadius: "10px",
            }}
          >
            <div className="row">
              <div className="fw-bolder mb-3 text-center">
                {data.Level2[randomNumber].sentence}
              </div>
            </div>

            <div className="row text-center">
              <div className="mb-2">
                {data.Level2[randomNumber].sentence
                  .split(" ")
                  .map((word, index) => (
                    <button
                      className="button mb-1"
                      key={index}
                      onClick={() => handleWordClick(word)}
                      disabled={
                        selectedNounArray.length >=
                        data.Level2[randomNumber].noun.nouns.length
                      }
                      style={{
                        backgroundColor: wordColors[word] || "#F5B946",
                        color: wordColors[word] ? "#FFFFFF" : "#000",
                        fontWeight: "bold",
                        cursor:
                          selectedNounArray.length >=
                          data.Level2[randomNumber].noun.nouns.length
                            ? "not-allowed"
                            : "pointer",
                      }}
                    >
                      {word}
                    </button>
                  ))}
              </div>
            </div>

            <div className="row text-center">
              <div className="mb-3">
                {word && (
                  <div>
                    {data.Level2[randomNumber].noun.nouns.includes(word) ? (
                      <div style={{ color: "#098B0D" }}>
                        <q>{word}</q> is a noun word.
                      </div>
                    ) : (
                      <div style={{ color: "#BF4C4C" }}>
                        <q>{word}</q> is not a noun word.
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
            <div className="row text-center">
              <div className="mb-3">
                {!isDisableButtons && (
                  <div style={{ color: "#BF4C4C" }}>
                    Please select the type of noun for <q>{word}</q>.
                  </div>
                )}
              </div>
            </div>
            <div className="row text-center">
              <div className="mb-3 d-flex flex-wrap justify-content-between gap-2">
                {nounButtons.map(
                  ({ label, bgcolor, color, textColor, key }) => (
                    <button
                      className="button"
                      key={key}
                      disabled={isDisableButtons}
                      onClick={() => handleButtonClick(key)}
                      style={{
                        backgroundColor: bgcolor || color,
                        color: bgcolor === "#F5B946" ? "#000" : "#FFFFFF",
                        fontWeight: "bold",
                        flexShrink: 0, // prevent buttons from shrinking too small
                        padding: "0.5rem 1rem",
                      }}
                    >
                      {label}
                    </button>
                  )
                )}
              </div>
            </div>
            <div className="row text-center">
              <div className="row justify-content-center">
                {showErrorMessage && (
                  <div style={{ color: "#BF4C4C" }}>
                    <q>{word}</q> is not{" "}
                    {nounType === "abstract noun" ? "an" : "a"} {nounType}.
                    Refer hint.
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="row mb-3">
            <div className="d-flex justify-content-around">
              <Button
                onClick={handleSkip}
                variant="contained"
                sx={{
                  background: "#0F477E",
                  color: "#ffffff",
                  fontSize: "calc(.6rem + .4vw)",
                }}
              >
                {t("skip")}
              </Button>
              <Button
                variant="contained"
                disabled={isDisableNext}
                onClick={handleNext}
                sx={{
                  background: "#0F477E",
                  color: "#ffffff",
                  fontSize: "calc(.6rem + .4vw)",
                }}
              >
                {randomNumberArray.length == 10 ? t("finish") : t("next")}
              </Button>
            </div>
          </div>

          <div className="row mb-3">
            {selectedNounArray.length >= 1 && (
              <div className="row text-center">
                <Table
                  className="text-center"
                  bordered
                  style={{ border: "1px solid black" }}
                >
                  <thead style={{ background: "#0F477E", color: "#ffffff" }}>
                    <tr>
                      <th>Sr. no.</th>
                      <th>Noun</th>
                      <th>Type of noun</th>
                    </tr>
                  </thead>
                  <tbody style={{ background: "#EDF6FA", color: "#000" }}>
                    {selectedNounArray.map((item, index) => (
                      <tr>
                        <td>{index + 1}</td>
                        <td>{item}</td>
                        <td>{nounTypeArray[index]}</td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </div>
            )}
          </div>

          <div className="row justify-content-center">
            {showMessage && !isDisableNext && (
              <div
                className="d-flex justify-content-center align-items-center"
                style={{
                  width: "auto",
                  height: "auto",
                  background: "#ffffff",
                  boxShadow: "0px 0px 5px rgba(0, 0, 0, 0.5)",
                  borderRadius: "50px",
                  padding: "1rem",
                }}
              >
                For this sentence &nbsp;
                <span style={{ color: "#098B0D", fontWeight: "bold" }}>
                  Noun and its types
                </span>
                &nbsp; identified successfully!
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <div>
              {!isDisableNext ? (
                <ul className="">
                  {randomNumberArray.length === 10 ? (
                    <li>{t("instr9")}</li>
                  ) : (
                    <li>{t("instr2_7")}</li>
                  )}
                </ul>
              ) : randomNumberArray.length > 10 == true ? (
                <ul className="">
                  <li>{t("instr2_9")}</li>
                </ul>
              ) : (
                <ul className="">
                  <li>{t("instr2_1")}</li>
                  <li>{t("instr2_2")}</li>
                  <li>{t("instr2_3")}</li>
                  <li>{t("instr2_4")}</li>
                  <li>{t("instr2_5")}</li>
                  <li>{t("instr2_6")}</li>
                  <li>
                    <u>{t("note")}</u>: {t("instr2_8")}
                  </li>
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>
      <InfoPopUpForDetailView
        openDialog={showDialogue}
        onAgree={onAgree}
        content={<ViewDetailsPopup hint={data.Level2[randomNumber].hint} />}
        popuptitle="Hint"
      />
    </div>
  );
};
